INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-07-malaysia-exemption-threshold-raised', '2026-01-07', '2026-01', 'Malaysia''s Cabinet has raised the permanent e-invoicing exemption threshold from RM500,000 to RM1 million turnover, and cancelled the previously planned Phase 5 (RM150,000-500,000) entirely.', '<h3>🇲🇾 LHDN raises the permanent exemption threshold to RM1 million, scraps the planned Phase 5</h3>
<p>Following a Cabinet decision in early December 2025, guidelines confirming the change have taken effect for 2026 planning: businesses with annual turnover below RM1 million are now permanently exempt from Malaysia''s e-invoicing mandate — double the previous RM500,000 threshold. Alongside this, LHDN has cancelled the previously planned Phase 5, which would have brought businesses turning over RM150,000 to RM500,000 into scope. That phase simply no longer exists.</p>
<p>Two details worth not missing here. First, exemption isn''t automatic — LHDN''s MSME criteria still apply, so falling under RM1 million in revenue doesn''t by itself guarantee exempt status without meeting the actual published conditions. Second, and more consequential: once a business has been brought into the mandate, it cannot re-qualify for exemption in a later year even if its revenue subsequently drops below RM1 million. Exemption is effectively a one-way gate — available before you''re mandated in, not something you can step back into afterward.</p>
<p><strong>What this means for your team:</strong> if your business sits comfortably under RM1 million and expects to stay there, this is genuinely good news — a permanently exempt category now exists where previously a forced Phase 5 entry was planned. But if your revenue is trending upward past that threshold, or fluctuates year to year, don''t assume a temporary dip below RM1 million later will undo an existing obligation — check your actual current standing against LHDN''s specific criteria rather than the headline number alone.</p>', 'https://www.hasil.gov.my/en/e-invoice', 1);
