INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-07-malaysia-exemption-threshold-raised', 'en', 'LHDN raises the permanent exemption threshold to RM1 million, scraps the planned Phase 5', 'Malaysia''s Cabinet has raised the permanent e-invoicing exemption threshold from RM500,000 to RM1 million turnover, and cancelled the previously planned Phase 5 (RM150,000-500,000) entirely.', '<h3>🇲🇾 LHDN raises the permanent exemption threshold to RM1 million, scraps the planned Phase 5</h3>
<p>Following a Cabinet decision in early December 2025, guidelines confirming the change have taken effect for 2026 planning: businesses with annual turnover below RM1 million are now permanently exempt from Malaysia''s e-invoicing mandate — double the previous RM500,000 threshold. Alongside this, LHDN has cancelled the previously planned Phase 5, which would have brought businesses turning over RM150,000 to RM500,000 into scope. That phase simply no longer exists.</p>
<p>Two details worth not missing here. First, exemption isn''t automatic — LHDN''s MSME criteria still apply, so falling under RM1 million in revenue doesn''t by itself guarantee exempt status without meeting the actual published conditions. Second, and more consequential: once a business has been brought into the mandate, it cannot re-qualify for exemption in a later year even if its revenue subsequently drops below RM1 million. Exemption is effectively a one-way gate — available before you''re mandated in, not something you can step back into afterward.</p>
<p><strong>What this means for your team:</strong> if your business sits comfortably under RM1 million and expects to stay there, this is genuinely good news — a permanently exempt category now exists where previously a forced Phase 5 entry was planned. But if your revenue is trending upward past that threshold, or fluctuates year to year, don''t assume a temporary dip below RM1 million later will undo an existing obligation — check your actual current standing against LHDN''s specific criteria rather than the headline number alone.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-malaysia-rm10000-individual-invoice-rule', '2026-01-01', '2026-01', 'From today, transactions above RM10,000 in Malaysia require an individual e-invoice — consolidated invoicing, bundling multiple transactions into one submission, is no longer permitted for amounts above that threshold.', '<h3>🇲🇾 Individual e-invoices become mandatory above RM10,000, ending blanket consolidated invoicing</h3>
<p>A practical operational change takes effect today, easy to miss amid the bigger Phase 4 threshold headlines: any single transaction exceeding RM10,000 now requires its own individual e-invoice. Consolidated e-invoicing — the common practice of bundling many smaller transactions into one periodic submission, widely used by retail, food and beverage, and other high-volume outlets — is no longer permitted once a single transaction crosses that RM10,000 line.</p>
<p>This matters specifically because consolidated invoicing has been a genuine relief valve for high-volume, low-value businesses during the relaxation period — LHDN has actually expanded which sectors qualify for it, including retail and building materials suppliers. The RM10,000 individual-invoice rule sits alongside that relief, not in place of it: most transactions can still be consolidated and submitted within seven calendar days of month-end, but any transaction over the threshold needs its own e-invoice, issued and validated at the time.</p>
<p><strong>What this means for your team:</strong> if your point-of-sale or billing system is currently configured to consolidate everything by default, confirm it can actually detect and break out individual transactions above RM10,000 rather than folding them into the next periodic batch. This is the kind of gap that doesn''t show up until a specific high-value sale goes through incorrectly — worth testing deliberately rather than discovering during an actual audit.</p>', 'https://www.hasil.gov.my/en/e-invoice', 1);
