INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-malaysia-rm10000-individual-invoice-rule', 'en', 'Individual e-invoices become mandatory above RM10,000, ending blanket consolidated invoicing', 'From today, transactions above RM10,000 in Malaysia require an individual e-invoice — consolidated invoicing, bundling multiple transactions into one submission, is no longer permitted for amounts above that threshold.', '<h3>🇲🇾 Individual e-invoices become mandatory above RM10,000, ending blanket consolidated invoicing</h3>
<p>A practical operational change takes effect today, easy to miss amid the bigger Phase 4 threshold headlines: any single transaction exceeding RM10,000 now requires its own individual e-invoice. Consolidated e-invoicing — the common practice of bundling many smaller transactions into one periodic submission, widely used by retail, food and beverage, and other high-volume outlets — is no longer permitted once a single transaction crosses that RM10,000 line.</p>
<p>This matters specifically because consolidated invoicing has been a genuine relief valve for high-volume, low-value businesses during the relaxation period — LHDN has actually expanded which sectors qualify for it, including retail and building materials suppliers. The RM10,000 individual-invoice rule sits alongside that relief, not in place of it: most transactions can still be consolidated and submitted within seven calendar days of month-end, but any transaction over the threshold needs its own e-invoice, issued and validated at the time.</p>
<p><strong>What this means for your team:</strong> if your point-of-sale or billing system is currently configured to consolidate everything by default, confirm it can actually detect and break out individual transactions above RM10,000 rather than folding them into the next periodic batch. This is the kind of gap that doesn''t show up until a specific high-value sale goes through incorrectly — worth testing deliberately rather than discovering during an actual audit.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-01-malaysia-phase4-relaxation-extended', '2026-03-01', '2026-03', 'LHDN has extended Phase 4''s penalty-free relaxation period from its original 2026 end date to 31 December 2027, meaning full enforcement under Section 120 for RM1m-5m turnover businesses doesn''t begin until 1 January 2028.', '<h3>🇲🇾 LHDN extends the Phase 4 relaxation period to the end of 2027, pushing full enforcement to 2028</h3>
<p>Businesses in Phase 4 — those with turnover between RM1 million and RM5 million, technically required to begin e-invoicing on 1 January 2026 — have been given meaningfully more breathing room than originally planned. LHDN has extended the relaxation period from its earlier 2026 end date out to 31 December 2027. Full enforcement, including real penalties under Section 120 of the Income Tax Act, now doesn''t begin until 1 January 2028.</p>
<p>Worth being precise about what "relaxation" actually permits, since it isn''t a free pass: during this window, businesses can issue consolidated e-invoices and use more flexible product/service descriptions, and won''t face Section 120 penalties for non-compliance. What it doesn''t do is remove the underlying obligation to register on MyInvois and show genuine, ongoing effort toward compliance — LHDN''s guidance is explicit that the relaxation period is for businesses actively transitioning, not a reason to defer starting entirely.</p>
<p><strong>What this means for your team:</strong> a full two extra years before real enforcement is a genuine gift of time, but it''s worth using deliberately rather than banking it as an excuse to wait until late 2027 to start. Businesses that register on MyInvois and begin issuing consolidated e-invoices now will have a far smoother transition to full individual-transaction compliance by 2028 than those who treat the extended deadline as license to do nothing until it''s nearly up.</p>', 'https://www.hasil.gov.my/en/e-invoice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-01-malaysia-phase4-relaxation-extended', id FROM countries WHERE name_en = 'Malaysia';
